<template>
  <main class="agent-page">
    <header class="agent-page__header"><h1>智能体</h1></header>
    <section class="agent-hero"><div><h2 class="agent-hero__title">配置你的专属智能体</h2><p>通过知识库和配置，让智能体更好地为团队服务</p></div><div class="agent-hero__bot" aria-hidden="true">◉</div><el-button data-testid="create-agent" type="primary" @click="showCreate = true"><el-icon><Plus /></el-icon>创建智能体</el-button></section>
    <section v-if="agentList.length" class="agent-metrics" aria-label="智能体概览"><article><span class="metric-icon">♙</span><div><small>智能体总数</small><strong>{{ agentList.length }}</strong></div></article><article><span class="metric-icon metric-icon--green">◉</span><div><small>运行中</small><strong>{{ agentList.length }}</strong></div></article></section>
    <section v-if="agentList.length" class="agent-workspace" aria-label="智能体列表">
      <div class="agent-workspace__title"><h2>智能体列表</h2><el-button type="primary" @click="showCreate = true"><el-icon><Plus /></el-icon>创建智能体</el-button></div>
      <div class="agent-toolbar"><el-input v-model="searchQuery" data-testid="agent-search" clearable placeholder="搜索智能体名称或描述"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="statusFilter" data-testid="agent-status-filter" aria-label="按状态筛选"><el-option label="全部状态" value="all" /><el-option label="运行中" value="running" /></el-select><el-button plain><el-icon><Filter /></el-icon>更多筛选</el-button></div>
      <div class="agent-grid"><article v-for="agent in filteredAgents" :key="agent.id" class="agent-card" tabindex="0" @click="goToDetail(agent.id)" @keyup.enter="goToDetail(agent.id)"><div class="agent-card__top"><span class="agent-card__avatar">{{ agent.name.slice(0, 1) }}</span><el-button text aria-label="更多操作">⋮</el-button></div><h3 class="agent-card__title">{{ agent.name }}</h3><p>{{ agent.description || '暂未添加描述' }}</p><div class="agent-card__tags"><span>智能体</span><span>知识库</span></div><footer><span>▧ 知识库：—</span><span class="agent-card__status">● 运行中</span><el-button :aria-label="`删除智能体 ${agent.name}`" text type="danger" @click.stop="handleDelete(agent.id)"><el-icon class="agent-card__delete-icon"><Delete /></el-icon></el-button></footer></article><button class="agent-card agent-card--new" type="button" @click="showCreate = true"><b>＋</b><span>从零开始创建你的智能体</span></button></div>
    </section>
    <section v-else class="empty-state agent-page__empty"><h2>还没有智能体</h2><p>创建第一个智能体，为团队提供稳定的专属协作入口。</p><el-button type="primary" @click="showCreate = true">创建智能体</el-button></section>
    <el-dialog v-model="showCreate" title="创建智能体" width="420px"><el-form ref="createFormRef" :model="createForm" :rules="rules" label-width="80px"><el-form-item label="名称" prop="name"><el-input v-model="createForm.name" /></el-form-item><el-form-item label="描述" prop="description"><el-input v-model="createForm.description" /></el-form-item></el-form><template #footer><el-button @click="showCreate=false">取消</el-button><el-button type="primary" :loading="loading" @click="handleCreate">创建</el-button></template></el-dialog>
  </main>
</template>
<script>
import { Delete, Filter, Plus, Search } from '@element-plus/icons-vue'
import { http } from '../api/http'
export default { name:'Agent', components:{Delete,Filter,Plus,Search}, data(){return {agentList:[],searchQuery:'',statusFilter:'all',showCreate:false,loading:false,createForm:{name:'',description:''},rules:{name:[{required:true,message:'请输入智能体名称',trigger:'blur'}],description:[{required:true,message:'请输入描述',trigger:'blur'}]}}}, computed:{filteredAgents(){const q=this.searchQuery.trim().toLowerCase();return this.agentList.filter(a=>!q||`${a.name} ${a.description||''}`.toLowerCase().includes(q))}}, mounted(){this.fetchAgentList()}, methods:{async fetchAgentList(){try{const res=await http.get('/agent/list');if(res.data?.code===200)this.agentList=Array.isArray(res.data.data)?res.data.data:res.data.data?[res.data.data]:[];else this.$message.error(res.data?.msg||'获取智能体失败')}catch(e){this.$message.error('网络错误，获取智能体失败')}},goToDetail(id){this.$router.push(`/agent/${id}`)},handleCreate(){this.$refs.createFormRef.validate(async valid=>{if(!valid)return;this.loading=true;try{const res=await http.post('/agent/add',this.createForm);if(res.data?.code===200){await this.fetchAgentList();this.showCreate=false;this.createForm={name:'',description:''};this.$message.success('创建成功！')}else this.$message.error(res.data?.msg||'创建失败')}catch(e){this.$message.error('网络错误，创建失败')}finally{this.loading=false}})},async handleDelete(id){this.$confirm('确定要删除该智能体吗？此操作不可恢复！','提示',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'}).then(async()=>{try{const res=await http.delete(`/agent/delete/${id}`);if(res.data?.code===200){this.$message.success('删除成功');this.fetchAgentList()}else this.$message.error(res.data?.msg||'删除失败')}catch(e){this.$message.error('网络错误，删除失败')}}).catch(()=>{})}}}
</script>
<style scoped>
.agent-page{padding:12px 0}.agent-page__header h1{margin:0 0 24px;color:var(--sea-deep);font-size:28px}.agent-hero{display:flex;align-items:center;gap:28px;min-height:148px;padding:25px 30px;border:1px solid #e2ebef;border-radius:12px;background:linear-gradient(105deg,#fff 35%,#effcfa);box-shadow:0 8px 24px #11243b0a}.agent-hero__title{margin:0;color:var(--sea-deep);font-size:23px}.agent-hero p{margin:9px 0 0;color:var(--sea-muted)}.agent-hero__bot{margin-left:auto;color:#09b9a2;font-size:72px;text-shadow:0 0 25px #78eee0}.agent-hero>.el-button{padding-inline:18px}.agent-metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:18px 0}.agent-metrics article{display:flex;align-items:center;gap:12px;padding:15px 20px;border:1px solid #e4edf1;border-radius:10px;background:#fff}.metric-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:#e9f2ff;color:#287cf2}.metric-icon--green{background:#e7faf2;color:#12b982}.agent-metrics small,.agent-metrics strong{display:block}.agent-metrics small{color:var(--sea-muted)}.agent-metrics strong{margin-top:3px;font-size:21px}.agent-workspace{padding:16px;border:1px solid #e2ebef;border-radius:12px;background:#fff;box-shadow:0 8px 24px #11243b0a}.agent-workspace__title{display:flex;align-items:center;justify-content:space-between}.agent-workspace h2{margin:0;font-size:20px}.agent-toolbar{display:flex;gap:12px;margin:14px 0 16px}.agent-toolbar .el-input{max-width:310px}.agent-toolbar .el-select{width:140px}.agent-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.agent-card{min-height:174px;padding:16px;border:1px solid #e4ecf1;border-radius:10px;background:#fff;text-align:left;transition:.18s}.agent-card:hover,.agent-card:focus-visible{border-color:#55cbbd;box-shadow:0 8px 20px #00a6a614}.agent-card__top{display:flex;justify-content:space-between}.agent-card__avatar{display:grid;place-items:center;width:40px;height:40px;border:1px solid #9bb7ff;border-radius:50%;background:#eff3ff;color:#345def;font-weight:700}.agent-card h3{margin:10px 0 5px;color:var(--sea-deep);font-size:16px}.agent-card p{height:20px;margin:0;overflow:hidden;color:var(--sea-muted);font-size:12px;text-overflow:ellipsis;white-space:nowrap}.agent-card__tags{display:flex;gap:7px;margin-top:10px}.agent-card__tags span{padding:3px 7px;border-radius:5px;background:#f1f5f8;color:#60728c;font-size:11px}.agent-card footer{display:flex;align-items:center;gap:8px;margin:15px -16px -16px;padding:10px 16px;border-top:1px solid #edf1f4;color:#71839a;font-size:11px}.agent-card__status{margin-left:auto;color:#0aae85}.agent-card--new{display:grid;place-items:center;border-style:dashed;color:var(--sea-muted);font:inherit}.agent-card--new b{display:grid;place-items:center;width:46px;height:46px;border:2px solid #09b493;border-radius:50%;color:#09b493;font-size:30px;font-weight:400}.agent-card--new span{margin-top:8px}.agent-page__empty{display:grid;place-items:center;min-height:280px}.agent-page__empty p{color:var(--sea-muted)}@media(max-width:900px){.agent-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){.agent-hero{align-items:flex-start;flex-wrap:wrap;padding:20px}.agent-hero__bot{display:none}.agent-hero>.el-button{width:100%}.agent-toolbar{flex-wrap:wrap}.agent-toolbar .el-input{flex-basis:100%;max-width:none}.agent-toolbar .el-select{flex:1}.agent-grid{grid-template-columns:1fr}.agent-metrics{gap:10px}}
</style>
